import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Harness code. Do not edit this file.
 *
 * Reads a command file and calls the methods it names. Each call is echoed as
 * ">>> name(args)" before it runs, so its output can be told apart from the
 * next one's.
 *
 * A command file holds one call per line: the method name followed by its
 * arguments, separated by spaces. Blank lines and lines starting with # are
 * ignored. See tests/commands.txt.
 *
 * If a method throws, the runner reports it and carries on with the next
 * command, so one failure does not stop the rest.
 */
public final class CommandRunner {

    /** Which class owns each command, used when running a single task. */
    private static String owner(String name) {
        switch (name) {
            case "getStationRank":
            case "getBusiestHour":
                return "StationActivity";
            case "getDirectServices":
                return "DirectServices";
            case "getStationsAtHops":
            case "getItinerary":
            case "getItineraryM1":
            case "getItineraryM2":
                return "JourneyPlanner";
            default:
                return null;
        }
    }

    private static final class Command {
        final String name;
        final String[] args;
        Command(String name, String[] args) { this.name = name; this.args = args; }
    }

    private static List<Command> parse(String path) throws IOException {
        List<Command> out = new ArrayList<>();
        try (BufferedReader in = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = in.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] parts = line.split("\\s+");
                String[] args = new String[parts.length - 1];
                System.arraycopy(parts, 1, args, 0, args.length);
                out.add(new Command(parts[0], args));
            }
        }
        return out;
    }

    /** Rebuilds the Java-style call text used in the ">>>" echo line. */
    private static String echo(String name, String[] a) {
        StringBuilder sb = new StringBuilder(name).append('(');
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(',');
            boolean numeric = ("getStationRank".equals(name))
                    || ("getStationsAtHops".equals(name) && i == 1)
                    || (name.startsWith("getItinerary") && i == 2);
            if (numeric) sb.append(a[i]);
            else sb.append('"').append(a[i]).append('"');
        }
        return sb.append(')').toString();
    }

    /**
     * Runs every command in the file. When onlyTask is null all commands run;
     * otherwise only those belonging to that class, so a single task can be
     * exercised while the others are still unimplemented.
     */
    public static void run(String path, String onlyTask) {
        List<Command> commands;
        try {
            commands = parse(path);
        } catch (IOException e) {
            System.out.println("Cannot read command file '" + path + "': " + e.getMessage());
            return;
        }

        StationActivity task1 = null;
        DirectServices task2 = null;
        JourneyPlanner task3 = null;

        for (Command c : commands) {
            String owner = owner(c.name);
            if (owner == null) {
                System.out.println(">>> " + c.name);
                System.out.println("Unknown command '" + c.name + "'.");
                continue;
            }
            if (onlyTask != null && !onlyTask.equals(owner)) continue;

            System.out.println(">>> " + echo(c.name, c.args));
            try {
                String[] a = c.args;
                switch (c.name) {
                    case "getStationRank":
                        if (task1 == null) task1 = new StationActivity();
                        task1.getStationRank(Integer.parseInt(a[0]));
                        break;
                    case "getBusiestHour":
                        if (task1 == null) task1 = new StationActivity();
                        task1.getBusiestHour(a[0]);
                        break;
                    case "getDirectServices":
                        if (task2 == null) task2 = new DirectServices();
                        task2.getDirectServices(a[0], a[1]);
                        break;
                    case "getStationsAtHops":
                        if (task3 == null) task3 = new JourneyPlanner();
                        task3.getStationsAtHops(a[0], Integer.parseInt(a[1]));
                        break;
                    case "getItinerary":
                        if (task3 == null) task3 = new JourneyPlanner();
                        task3.getItinerary(a[0], a[1], Integer.parseInt(a[2]));
                        break;
                    case "getItineraryM1":
                        if (task3 == null) task3 = new JourneyPlanner();
                        task3.getItineraryM1(a[0], a[1], Integer.parseInt(a[2]));
                        break;
                    case "getItineraryM2":
                        if (task3 == null) task3 = new JourneyPlanner();
                        task3.getItineraryM2(a[0], a[1], Integer.parseInt(a[2]));
                        break;
                    default:
                        System.out.println("Unknown command '" + c.name + "'.");
                }
            } catch (ArrayIndexOutOfBoundsException e) {
                System.out.println("Wrong number of arguments for '" + c.name + "'.");
            } catch (NumberFormatException e) {
                System.out.println("Expected a number in '" + c.name + "': " + e.getMessage());
            } catch (RuntimeException | StackOverflowError e) {
                System.out.println("Error in " + c.name + ": " + e);
            }
        }
    }

    /** Command file to use when none is named on the command line. */
    public static String fileFrom(String[] args) {
        return args.length > 0 ? args[0] : "tests/commands.txt";
    }

    private CommandRunner() { }
}
